 return {"result":{"score_policy":"ai_gate/risk_v1","score":None,"grade":None,"grade_reliable":complete,"risk_assessment_state":state},"findings":findings,"coverage":{"status":"complete" if complete else "partial","reasons":[] if complete else ["boundary_controls_or_attacks_incomplete",*summary["errors"]]},"ai_gate":{"probe_pack":PACK,"scan_profile":"standard","target_type":target.get("target_type","api_chat"),"target_name":target.get("name"),"boundary":summary,"runtime_destinations":dest,"transcripts":[transcript],"statistics":stats,"errors":summary["errors"],"control_evidence":{},"execution_plan":{"mode":"boundary_contract","executed":[PROBE_ID],"boundary":summary,"request_records":records,"semantic_judge":{"enabled":False,"status":"not_required_deterministic_proof"}},"coverage_matrix":{"boundary_complete":complete,"boundary_state":state,"attempted_attacks":summary["attempted_attacks"],"planned_attempts":summary["planned_attempts"]},"usage":{**request_usage,**token_usage},"transcript_retention":{"redaction_applied":True,"transcript_sensitivity":"internal","include_sensitive_available":False,"raw_response_bodies_stored":False},"decision":{"decision":decision,"rationale":rationale,"policy_name":f"ai-gate:{PACK}-v1","environment":environment,"severity_counts":counts,"evidence":{"statistics":stats,"boundary":summary}}}}
